import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ChevronLeft, ChevronRight, Loader2 } from "lucide-react";
import { productService } from "@/services/productService";

export function InventoryTable({ filters = {}, searchQuery = "", limit = 25, onPageChange, currentPage = 1 }) {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 25,
    total: 0,
    pages: 0
  });

  useEffect(() => {
    fetchProducts();
  }, [filters, searchQuery, limit, currentPage]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const params = {
        page: currentPage,
        limit: limit,
        ...(searchQuery && { q: searchQuery }),
        ...Object.fromEntries(
          Object.entries(filters).filter(([_, value]) => value !== "" && value !== undefined)
        )
      };

      const response = await productService.getProducts(params);
      setProducts(response.data || []);
      setPagination(response.pagination || {
        page: 1,
        limit: 25,
        total: 0,
        pages: 0
      });
    } catch (error) {
      console.error("Error fetching products:", error);
      setProducts([]);
      setPagination({
        page: 1,
        limit: 25,
        total: 0,
        pages: 0
      });
    } finally {
      setLoading(false);
    }
  };

  const handlePageChange = (page) => {
    if (onPageChange) {
      onPageChange(page);
    }
  };

  const renderPaginationButtons = () => {
    const buttons = [];
    const { page, pages } = pagination;

    // Previous button
    buttons.push(
      <Button
        key="prev"
        variant="outline"
        size="sm"
        className="h-8 bg-transparent"
        disabled={page <= 1}
        onClick={() => handlePageChange(page - 1)}
      >
        <ChevronLeft className="w-4 h-4" />
        Trước
      </Button>
    );

    // Page numbers
    const pageNumbers = [];
    const maxVisiblePages = 5;

    if (pages <= maxVisiblePages) {
      // Show all pages if total pages is small
      for (let i = 1; i <= pages; i++) {
        pageNumbers.push(i);
      }
    } else {
      // Show pages around current page
      const startPage = Math.max(1, page - 2);
      const endPage = Math.min(pages, page + 2);

      if (startPage > 1) {
        pageNumbers.push(1);
        if (startPage > 2) pageNumbers.push("...");
      }

      for (let i = startPage; i <= endPage; i++) {
        pageNumbers.push(i);
      }

      if (endPage < pages) {
        if (endPage < pages - 1) pageNumbers.push("...");
        pageNumbers.push(pages);
      }
    }

    pageNumbers.forEach((pageNum, index) => {
      if (pageNum === "...") {
        buttons.push(
          <span key={`ellipsis-${index}`} className="text-muted-foreground">
            ...
          </span>
        );
      } else {
        buttons.push(
          <Button
            key={pageNum}
            variant={pageNum === page ? "default" : "outline"}
            size="sm"
            className={`h-8 w-8 ${
              pageNum === page
                ? "bg-medical-blue hover:bg-medical-blue/90"
                : "bg-transparent"
            }`}
            onClick={() => handlePageChange(pageNum)}
          >
            {pageNum}
          </Button>
        );
      }
    });

    // Next button
    buttons.push(
      <Button
        key="next"
        variant="outline"
        size="sm"
        className="h-8 bg-transparent"
        disabled={page >= pages}
        onClick={() => handlePageChange(page + 1)}
      >
        Sau
        <ChevronRight className="w-4 h-4" />
      </Button>
    );

    return buttons;
  };

  if (loading) {
    return (
      <Card className="border-0 shadow-sm">
        <CardContent className="p-12 flex items-center justify-center">
          <Loader2 className="w-5 h-5 animate-spin mr-2" />
          Đang tải danh sách thuốc...
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-0 shadow-sm">
      <CardContent className="p-0">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-muted/50">
              <tr>
                <th className="text-left p-4 font-medium text-foreground">
                  Mã thuốc
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Tên thuốc
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Danh mục thuốc
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Mô tả
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Đơn vị
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Nhà cung cấp
                </th>
                <th className="text-left p-4 font-medium text-foreground">
                  Hạn sử dụng
                </th>
              </tr>
            </thead>
            <tbody>
              {products.length === 0 ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center text-muted-foreground">
                    Không có dữ liệu thuốc nào
                  </td>
                </tr>
              ) : (
                products.map((item, index) => (
                  <tr
                    key={item.id || item.sku || index}
                    className={`border-b border-border ${
                      index % 2 === 0 ? "bg-background" : "bg-muted/20"
                    }`}
                  >
                    <td className="p-4">
                      <span className="font-mono text-sm text-medical-blue font-medium">
                        {item.sku || item.id}
                      </span>
                    </td>
                    <td className="p-4">
                      <p className="font-medium text-foreground">{item.name}</p>
                    </td>
                    <td className="p-4 text-muted-foreground">
                      {item.category?.name || item.category}
                    </td>
                    <td className="p-4 text-muted-foreground">
                      {item.description || item.activeIngredient}
                    </td>
                    <td className="p-4 text-muted-foreground">{item.unit}</td>
                    <td className="p-4 text-muted-foreground">
                      {item.supplier?.name || item.supplier}
                    </td>
                    <td className="p-4 text-muted-foreground">
                      {item.expiryDate ? new Date(item.expiryDate).toLocaleDateString('vi-VN') : 'N/A'}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex items-center justify-between p-4 border-t border-border">
          <div className="text-sm text-muted-foreground">
            Hiển thị{" "}
            <span className="font-medium text-foreground">
              {products.length > 0 ? ((pagination.page - 1) * pagination.limit) + 1 : 0}-
              {Math.min(pagination.page * pagination.limit, pagination.total)}
            </span>{" "}
            trong tổng số{" "}
            <span className="font-medium text-foreground">{pagination.total}</span> thuốc
          </div>

          <div className="flex items-center space-x-2">
            {renderPaginationButtons()}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
