import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Trash2, CheckCircle, Loader2 } from 'lucide-react';
import { supplierService } from '@/services/supplierService';
import { transactionService } from '@/services/transactionService';
import { categoryService } from '@/services/categoryService';

export function ImportReceiptForm() {
  const [suppliers, setSuppliers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [formData, setFormData] = useState({ supplierId: '', transactionDate: new Date().toISOString().split('T')[0], notes: '' });
  const [drugItems, setDrugItems] = useState([{ id: '1', productName: '', sku: '', unit: '', categoryId: '', quantity: '', unitPrice: '', lotNumber: '', expiryDate: '', total: 0 }]);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [suppliersResponse, categoriesResponse] = await Promise.all([
        supplierService.getSuppliers({ limit: 100, status: 'active' }),
        categoryService.getCategories({ limit: 100 })
      ]);
      setSuppliers(suppliersResponse.data);
      setCategories(categoriesResponse.data);
    } catch (error) {
      alert('Không thể tải danh sách nhà cung cấp hoặc danh mục');
    } finally {
      setLoading(false);
    }
  };

  const addDrugItem = () => setDrugItems([...drugItems, { id: Date.now().toString(), productName: '', sku: '', unit: '', categoryId: '', quantity: '', unitPrice: '', lotNumber: '', expiryDate: '', total: 0 }]);

  const removeDrugItem = (id) => { if (drugItems.length > 1) setDrugItems(drugItems.filter(item => item.id !== id)); };

  const updateDrugItem = (id, field, value) => {
    setDrugItems(drugItems.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        if (field === 'quantity' || field === 'unitPrice') {
          const qty = Number.parseFloat(field === 'quantity' ? value : item.quantity) || 0;
          const price = Number.parseFloat(field === 'unitPrice' ? value : item.unitPrice) || 0;
          updated.total = qty * price;
        }
        return updated;
      }
      return item;
    }));
  };

  const handleSubmit = async () => {
    if (!formData.supplierId) { alert('Vui lòng chọn nhà cung cấp'); return; }
    const validItems = drugItems.filter(i => i.productName && i.sku && i.unit && i.quantity && i.unitPrice);
    if (validItems.length === 0) { alert('Vui lòng thêm ít nhất một sản phẩm hợp lệ'); return; }
    
    try {
      setSubmitting(true);
      await transactionService.createInboundTransaction({
        supplierId: formData.supplierId,
        transactionDate: new Date(formData.transactionDate).toISOString(),
        notes: formData.notes,
        details: validItems.map(i => ({ productName: i.productName, sku: i.sku, unit: i.unit, categoryId: i.categoryId || undefined, quantity: Number(i.quantity), unitPrice: Number(i.unitPrice), lotNumber: i.lotNumber || undefined, expiryDate: i.expiryDate ? new Date(i.expiryDate).toISOString() : undefined }))
      });
      alert('Tạo phiếu nhập kho thành công!');
      setFormData({ supplierId: '', transactionDate: new Date().toISOString().split('T')[0], notes: '' });
      setDrugItems([{ id: '1', productName: '', sku: '', unit: '', categoryId: '', quantity: '', unitPrice: '', lotNumber: '', expiryDate: '', total: 0 }]);
    } catch (error) {
      alert(error.response?.data?.message || 'Không thể tạo phiếu nhập kho');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <Card className='border-0 shadow-sm'><CardContent className='p-12 flex items-center justify-center'><Loader2 className='w-5 h-5 animate-spin mr-2' />Đang tải...</CardContent></Card>;

  return (<div className='space-y-6'><Card className='border-0 shadow-sm'><CardHeader className='pb-4'><CardTitle className='text-lg font-semibold'>Thông tin chung</CardTitle></CardHeader><CardContent className='space-y-6'><div className='grid grid-cols-1 md:grid-cols-2 gap-6'><div className='space-y-2'><Label>Nhà cung cấp *</Label><Select value={formData.supplierId} onValueChange={v => setFormData({...formData, supplierId: v})}><SelectTrigger><SelectValue placeholder='Chọn nhà cung cấp' /></SelectTrigger><SelectContent>{suppliers.map(s => <SelectItem key={s.id} value={s.id}>{s.name} ({s.code})</SelectItem>)}</SelectContent></Select></div><div className='space-y-2'><Label>Ngày nhập *</Label><Input type='date' value={formData.transactionDate} onChange={e => setFormData({...formData, transactionDate: e.target.value})} /></div></div><div className='space-y-2'><Label>Ghi chú</Label><Textarea placeholder='Ghi chú...' value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} rows={3} /></div></CardContent></Card><Card className='border-0 shadow-sm'><CardHeader className='pb-4'><div className='flex items-center justify-between'><div><CardTitle className='text-lg font-semibold'>Chi tiết phiếu nhập</CardTitle><p className='text-sm text-muted-foreground mt-1'>Nhập thông tin sản phẩm mới</p></div><Button onClick={addDrugItem} className='bg-medical-blue hover:bg-medical-blue/90 text-black'><Plus className='w-4 h-4 mr-2' />Thêm sản phẩm</Button></div></CardHeader><CardContent><div className='overflow-x-auto'><table className='w-full'>            <thead className='bg-muted/50'><tr><th className='text-left p-3'>Tên sản phẩm *</th><th className='text-left p-3'>Mã SKU *</th><th className='text-left p-3'>Danh mục</th><th className='text-left p-3'>Đơn vị *</th><th className='text-left p-3'>Số lượng *</th><th className='text-left p-3'>Đơn giá *</th><th className='text-left p-3'>Số lô</th><th className='text-left p-3'>Hạn SD</th><th className='text-left p-3'>Thành tiền</th><th className='w-[60px]'></th></tr></thead><tbody>{drugItems.map((item, idx) =>                 <tr key={item.id} className={idx % 2 === 0 ? 'bg-background' : 'bg-muted/20'}><td className='p-3'><Input placeholder='VD: Paracetamol 500mg' value={item.productName} onChange={e => updateDrugItem(item.id, 'productName', e.target.value)} /></td><td className='p-3'><Input placeholder='PARA500' value={item.sku} onChange={e => updateDrugItem(item.id, 'sku', e.target.value)} /></td><td className='p-3'><Select value={item.categoryId} onValueChange={v => updateDrugItem(item.id, 'categoryId', v)}><SelectTrigger className='h-9'><SelectValue placeholder='Chọn danh mục' /></SelectTrigger><SelectContent>{categories.map(c => <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}</SelectContent></Select></td><td className='p-3'><Input placeholder='viên' value={item.unit} onChange={e => updateDrugItem(item.id, 'unit', e.target.value)} /></td><td className='p-3'><Input type='number' value={item.quantity} onChange={e => updateDrugItem(item.id, 'quantity', e.target.value)} min='1' /></td><td className='p-3'><Input type='number' value={item.unitPrice} onChange={e => updateDrugItem(item.id, 'unitPrice', e.target.value)} min='0' /></td><td className='p-3'><Input placeholder='Số lô' value={item.lotNumber} onChange={e => updateDrugItem(item.id, 'lotNumber', e.target.value)} /></td><td className='p-3'><Input type='date' value={item.expiryDate} onChange={e => updateDrugItem(item.id, 'expiryDate', e.target.value)} /></td><td className='p-3'><div className='font-medium'>{item.total.toLocaleString('vi-VN')} </div></td><td className='p-3'><Button variant='ghost' size='sm' onClick={() => removeDrugItem(item.id)} disabled={drugItems.length === 1} className='h-8 w-8 p-0 text-destructive'><Trash2 className='w-4 h-4' /></Button></td></tr>)}</tbody></table></div></CardContent></Card><Card className='border-0 shadow-sm'><CardHeader className='pb-4'><CardTitle>Tổng kết</CardTitle></CardHeader><CardContent><div className='flex justify-between py-2'><span>Tổng thành tiền:</span><span className='text-xl font-bold text-medical-blue'>{drugItems.reduce((sum, i) => sum + i.total, 0).toLocaleString('vi-VN')} </span></div></CardContent></Card><div className='flex justify-end pt-6'><Button onClick={handleSubmit} disabled={submitting} className='px-6 bg-calm-green hover:bg-calm-green/90 text-white'>{submitting ? <><Loader2 className='w-4 h-4 mr-2 animate-spin' />Đang xử lý...</> : <><CheckCircle className='w-4 h-4 mr-2' />Hoàn thành</>}</Button></div></div>);
}
